"use server";

import { revalidatePath } from "next/cache";

import { obterStatusLista } from "@/features/listas/consultas";
import { definirLista } from "@/features/listas/gravar";
import { listaSchema } from "@/features/listas/schema";
import { createClient } from "@/lib/supabase/server";

export type EstadoLista = { mensagem?: string };

const ERRO_GENERICO = "Não foi possível atualizar sua lista agora. Tente de novo.";

/**
 * Põe o filme na lista pedida; se ele já estava nela, tira (clicar de novo desfaz).
 * Os dados do filme vêm do TMDB no servidor, não do navegador.
 */
export async function alternarLista(
  _anterior: EstadoLista,
  formData: FormData,
): Promise<EstadoLista> {
  const resultado = listaSchema.safeParse({
    tmdbId: Number(formData.get("tmdbId")),
    status: formData.get("status"),
  });
  if (!resultado.success) return { mensagem: ERRO_GENERICO };
  const { tmdbId, status } = resultado.data;

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return { mensagem: "Sua sessão expirou. Entre de novo." };

  const atual = await obterStatusLista(tmdbId, supabase);
  const gravado = await definirLista(supabase, user.id, tmdbId, atual === status ? null : status);
  if (!gravado.ok) {
    return { mensagem: gravado.erro === "filme-nao-encontrado" ? "Filme não encontrado." : ERRO_GENERICO };
  }

  revalidatePath(`/filme/${tmdbId}`);
  revalidatePath("/listas");
  revalidatePath("/dashboard");
  return {};
}
import "server-only";

import type { StatusLista } from "@/features/listas/opcoes";
import type { ClienteSupabase } from "@/lib/supabase/token";
import { obterFilme } from "@/lib/tmdb/filmes";
import type { FilmeDetalhes } from "@/lib/tmdb/tipos";

export type ResultadoDefinir<T> =
  | { ok: true; titulo: string | null; anterior: T | null; atual: T | null }
  | { ok: false; erro: "filme-nao-encontrado" | "tmdb" | "banco" };

type BuscarFilme = (id: number) => Promise<FilmeDetalhes | null>;

/**
 * Deixa o filme na lista pedida (`null` tira das listas). É idempotente: repetir não muda nada.
 * Os dados do filme vêm do TMDB no servidor, nunca de quem chama.
 */
export async function definirLista(
  supabase: ClienteSupabase,
  usuarioId: string,
  tmdbId: number,
  status: StatusLista | null,
  buscarFilme: BuscarFilme = obterFilme,
): Promise<ResultadoDefinir<StatusLista>> {
  const { data: atual, error: erroLeitura } = await supabase
    .from("lista_itens")
    .select("status, titulo")
    .eq("tmdb_id", tmdbId)
    .maybeSingle();
  if (erroLeitura) {
    console.error("[listas] falha ao ler:", erroLeitura.code, erroLeitura.message);
    return { ok: false, erro: "banco" };
  }
  const anterior = atual?.status ?? null;

  if (status === null) {
    if (atual) {
      const { error } = await supabase.from("lista_itens").delete().eq("tmdb_id", tmdbId);
      if (error) {
        console.error("[listas] falha ao remover:", error.code, error.message);
        return { ok: false, erro: "banco" };
      }
    }
    return { ok: true, titulo: atual?.titulo ?? null, anterior, atual: null };
  }

  if (atual && anterior === status) return { ok: true, titulo: atual.titulo, anterior, atual: status };

  let filme: FilmeDetalhes | null;
  try {
    filme = await buscarFilme(tmdbId);
  } catch {
    return { ok: false, erro: "tmdb" };
  }
  if (!filme) return { ok: false, erro: "filme-nao-encontrado" };

  const { error } = await supabase.from("lista_itens").upsert({
    usuario_id: usuarioId,
    tmdb_id: tmdbId,
    status,
    titulo: filme.titulo,
    poster_path: filme.posterPath,
    ano: filme.ano,
    generos: filme.generos.map((genero) => genero.id),
    // Ao entrar ou trocar de lista, o filme vai para o topo da aba.
    adicionado_em: new Date().toISOString(),
  });
  if (error) {
    console.error("[listas] falha ao salvar:", error.code, error.message);
    return { ok: false, erro: "banco" };
  }
  return { ok: true, titulo: filme.titulo, anterior, atual: status };
}
import type { Database } from "@/lib/supabase/database.types";

export type StatusLista = Database["public"]["Enums"]["status_lista"];

export const STATUS_LISTA = ["quero_assistir", "assistido"] as const satisfies StatusLista[];

export const ROTULOS_STATUS: Record<StatusLista, string> = {
  quero_assistir: "Quero assistir",
  assistido: "Já assisti",
};

export type Aba = "quero" | "assistidos";

export const STATUS_DA_ABA: Record<Aba, StatusLista> = {
  quero: "quero_assistir",
  assistidos: "assistido",
};
import { z } from "zod";

import { STATUS_LISTA } from "@/features/listas/opcoes";
import { tmdbIdSchema } from "@/features/reacoes/schema";

export const listaSchema = z.object({
  tmdbId: tmdbIdSchema,
  status: z.enum(STATUS_LISTA),
});

