"use client";

import { cn } from "cn";
import { Heart, ThumbsDown, ThumbsUp, type LucideIcon } from "lucide-react";
import { useActionState, useState } from "react";

import { alternarReacao } from "@/features/reacoes/actions";
import { REACOES, ROTULOS_REACAO, type Reacao } from "@/features/reacoes/opcoes";

const ICONES: Record<Reacao, LucideIcon> = {
  "nao-gostei": ThumbsDown,
  gostei: ThumbsUp,
  amei: Heart,
};

/**
 * "Não é pra mim", "Gostei" e "Amei". Cada botão envia um formulário (funciona sem JS);
 * com JS, o destaque muda na hora e volta atrás se a ação falhar.
 */
export function BotoesReacao({ tmdbId, atual }: { tmdbId: number; atual: Reacao | null }) {
  const [estado, formAction, enviando] = useActionState(alternarReacao, {});
  // Enquanto a ação roda, mostra o resultado esperado; depois, vale o que veio do servidor.
  const [palpite, setPalpite] = useState<Reacao | null>(atual);
  const exibida = enviando ? palpite : atual;

  return (
    <div className="flex flex-col gap-2">
      <div role="group" aria-label="O que achou?" className="flex flex-wrap gap-2">
        {REACOES.map((reacao) => {
          const Icone = ICONES[reacao];
          const marcada = exibida === reacao;
          return (
            <form
              key={reacao}
              action={formAction}
              onSubmit={() => setPalpite(atual === reacao ? null : reacao)}
            >
              <input type="hidden" name="tmdbId" value={tmdbId} />
              <input type="hidden" name="reacao" value={reacao} />
              <button
                type="submit"
                aria-pressed={marcada}
                disabled={enviando}
                className={cn(
                  "border-border bg-background/60 inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm transition-colors outline-none",
                  "hover:bg-muted focus-visible:ring-ring/50 focus-visible:ring-3 disabled:opacity-70",
                  marcada &&
                    "border-primary bg-primary text-primary-foreground hover:bg-primary/80",
                )}
              >
                <Icone className={cn("size-4", marcada && reacao === "amei" && "fill-current")} />
                {ROTULOS_REACAO[reacao]}
              </button>
            </form>
          );
        })}
      </div>
      {estado.mensagem && (
        <p role="alert" className="text-destructive text-sm">
          {estado.mensagem}
        </p>
      )}
    </div>
  );
}
import { beforeAll, describe, expect, it } from "vitest";

import { criarUsuario } from "../../support/supabase-local";

describe("RLS das métricas", () => {
  let a: Awaited<ReturnType<typeof criarUsuario>>;
  let b: Awaited<ReturnType<typeof criarUsuario>>;

  beforeAll(async () => {
    a = await criarUsuario("Usuária A");
    b = await criarUsuario("Usuário B");
  });

  it("o usuário registra o próprio evento, mas não lê nenhum evento", async () => {
    const { error } = await a.cliente
      .from("eventos")
      .insert({ nome: "trailer_aberto", dados: { origem: "filme" } });
    expect(error).toBeNull();

    const leitura = await a.cliente.from("eventos").select("nome");
    expect(leitura.data).toEqual([]);
  });

  it("o usuário não registra evento em nome de outro", async () => {
    const { error } = await a.cliente
      .from("eventos")
      .insert({ usuario_id: b.id, nome: "wizard_iniciado" });
    expect(error?.code).toBe("42501");
  });

  it("o banco recusa evento fora da lista e clima do wizard nos dados", async () => {
    const desconhecido = await a.cliente.from("eventos").insert({ nome: "login" });
    expect(desconhecido.error?.code).toBe("23514");

    const comHumor = await a.cliente
      .from("eventos")
      .insert({ nome: "wizard_concluido", dados: { humor: "cansado" } });
    expect(comHumor.error?.code).toBe("23514");
  });

  it("registrar_clima conta sem expor a contagem nem a equipe", async () => {
    const registro = await a.cliente.rpc("registrar_clima", {
      p_humor: "cansado",
      p_experiencia: "rir",
      p_companhia: "a-dois",
    });
    expect(registro.error).toBeNull();

    const invalido = await a.cliente.rpc("registrar_clima", {
      p_humor: "feliz",
      p_experiencia: "rir",
      p_companhia: "a-dois",
    });
    expect(invalido.error?.code).toBe("23514");

    expect((await a.cliente.from("contagem_climas").select("total")).data).toEqual([]);
    expect((await a.cliente.from("equipe_metricas").select("usuario_id")).data).toEqual([]);
  });

  it("os totais só respondem a quem está na equipe", async () => {
    const eventos = await a.cliente.rpc("metricas_eventos");
    expect(eventos.error?.code).toBe("42501");

    const climas = await b.cliente.rpc("metricas_climas");
    expect(climas.error?.code).toBe("42501");
  });
});
