import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { escolherFilme, exibirComoFoi, responderComoFoi } from "@/features/como-foi/actions";
import { obterComoFoi } from "@/features/como-foi/consultas";
import { contarExibicao, gravarResposta } from "@/features/como-foi/gravar";
import { definirLista } from "@/features/listas/gravar";
import { definirReacao } from "@/features/reacoes/gravar";
import { createClient } from "@/lib/supabase/server";
import { obterFilme } from "@/lib/tmdb/filmes";

import { detalhes } from "../mcp/fakes";

vi.mock("next/cache", () => ({ revalidatePath: vi.fn() }));
vi.mock("@/lib/supabase/server", () => ({ createClient: vi.fn() }));
vi.mock("@/lib/tmdb/filmes", () => ({ obterFilme: vi.fn() }));
vi.mock("@/features/reacoes/gravar", () => ({ definirReacao: vi.fn() }));
vi.mock("@/features/listas/gravar", () => ({ definirLista: vi.fn() }));

type Erro = { code: string; message: string } | null;
type Chamada = { tabela: string; op: string; valor?: unknown; filtros: [string, unknown][] };

/** Supabase falso: toda leitura devolve `linha`; guarda cada escrita com os filtros. */
function bancoFalso({ linha = null as object | null, erro = null as Erro } = {}) {
  const chamadas: Chamada[] = [];
  const from = (tabela: string) => {
    const chamada: Chamada = { tabela, op: "select", filtros: [] };
    chamadas.push(chamada);
    const resposta = () => ({ data: chamada.op === "select" ? linha : null, error: erro });
    const consulta = {
      select: () => consulta,
      order: () => consulta,
      limit: () => consulta,
      insert: (valor: unknown) => Object.assign(chamada, { op: "insert", valor }) && consulta,
      update: (valor: unknown) => Object.assign(chamada, { op: "update", valor }) && consulta,
      eq: (coluna: string, valor: unknown) => {
        chamada.filtros.push([coluna, valor]);
        return consulta;
      },
      maybeSingle: () => Promise.resolve(resposta()),
      then: (ok: (r: ReturnType<typeof resposta>) => unknown) => Promise.resolve(resposta()).then(ok),
    };
    return consulta;
  };
  const escritas = () => chamadas.filter((c) => c.op !== "select");
  return { cliente: { from } as never, chamadas, escritas };
}

function logado(usuario: { id: string } | null, banco = bancoFalso()) {
  vi.mocked(createClient).mockResolvedValue({
    ...(banco.cliente as object),
    auth: { getUser: async () => ({ data: { user: usuario } }) },
  } as never);
  return banco;
}

const horasAtras = (horas: number) => new Date(Date.now() - horas * 3_600_000).toISOString();

function escolha(sobrescrever: object = {}) {
  return {
    id: 7,
    tmdb_id: 550,
    titulo: "Clube da Luta",
    escolhido_em: horasAtras(20),
    perguntado_em: null,
    vezes_perguntado: 0,
    respondido_em: null,
    ...sobrescrever,
  };
}

function formulario(dados: Record<string, string>) {
  const form = new FormData();
  for (const [chave, valor] of Object.entries(dados)) form.set(chave, valor);
  return form;
}

const OK = { ok: true, titulo: "Clube da Luta", anterior: null, atual: null } as const;

beforeEach(() => {
  vi.spyOn(console, "error").mockImplementation(() => {});
  vi.mocked(definirReacao).mockResolvedValue({ ...OK, atual: "amei" });
  vi.mocked(definirLista).mockResolvedValue({ ...OK, atual: "assistido" });
});
afterEach(() => vi.clearAllMocks());

describe("escolherFilme", () => {
  it("grava o filme com o título do TMDB e tipo filme", async () => {
    const banco = logado({ id: "u-1" });
    vi.mocked(obterFilme).mockResolvedValue(detalhes(550, { titulo: "Clube da Luta" }));

    expect(await escolherFilme(550)).toEqual({});
    expect(banco.escritas()).toEqual([
      {
        tabela: "escolhas_noite",
        op: "insert",
        valor: { tipo: "filme", tmdb_id: 550, titulo: "Clube da Luta" },
        filtros: [],
      },
    ]);
  });

  it.each([
    ["sem sessão", null, 550, "Sua sessão expirou. Entre de novo."],
    ["com ID inválido", { id: "u-1" }, 0, "Filme não encontrado."],
    ["com filme inexistente", { id: "u-1" }, 999, "Filme não encontrado."],
  ])("não grava nada %s", async (_caso, usuario, tmdbId, mensagem) => {
    const banco = logado(usuario);
    vi.mocked(obterFilme).mockResolvedValue(null);

    expect(await escolherFilme(tmdbId)).toEqual({ mensagem });
    expect(banco.escritas()).toEqual([]);
  });

  it("devolve erro quando o TMDB falha", async () => {
    const banco = logado({ id: "u-1" });
    vi.mocked(obterFilme).mockRejectedValue(new Error("fora do ar"));

    expect((await escolherFilme(550)).mensagem).toMatch(/Não foi possível guardar/);
    expect(banco.escritas()).toEqual([]);
  });
});

describe("obterComoFoi", () => {
  it("lê só a escolha mais recente e devolve a pergunta", async () => {
    const banco = bancoFalso({ linha: escolha() });

    expect(await obterComoFoi(banco.cliente)).toEqual({ id: 7, tmdbId: 550, titulo: "Clube da Luta" });
  });

  it.each([
    ["escolhida há 1 hora", { escolhido_em: horasAtras(1) }],
    ["já respondida", { respondido_em: horasAtras(1) }],
    ["perguntada 2 vezes", { vezes_perguntado: 2, perguntado_em: horasAtras(10) }],
  ])("devolve null para escolha %s", async (_caso, dados) => {
    expect(await obterComoFoi(bancoFalso({ linha: escolha(dados) }).cliente)).toBeNull();
  });

  it("devolve null sem escolha e quando o banco falha", async () => {
    expect(await obterComoFoi(bancoFalso().cliente)).toBeNull();
    const erro = { code: "500", message: "fora" };
    expect(await obterComoFoi(bancoFalso({ linha: escolha(), erro }).cliente)).toBeNull();
  });
});

describe("exibirComoFoi", () => {
  it("numa visita nova, soma uma pergunta e registra como_foi_exibido", async () => {
    const banco = logado({ id: "u-1" }, bancoFalso({ linha: escolha({ vezes_perguntado: 1, perguntado_em: horasAtras(20) }) }));

    await exibirComoFoi(7);

    const [update, evento] = banco.escritas();
    expect(update).toMatchObject({
      tabela: "escolhas_noite",
      valor: { vezes_perguntado: 2 },
      filtros: [["id", 7], ["vezes_perguntado", 1]],
    });
    expect(evento).toMatchObject({ tabela: "eventos", valor: { nome: "como_foi_exibido", dados: {} } });
  });

  it("na mesma visita, não grava nada", async () => {
    const banco = bancoFalso({ linha: escolha({ vezes_perguntado: 1, perguntado_em: horasAtras(0.2) }) });

    expect(await contarExibicao(banco.cliente, 7)).toBe(false);
    expect(banco.escritas()).toEqual([]);
  });

  it("não grava nada sem sessão ou com ID inválido", async () => {
    const banco = logado(null, bancoFalso({ linha: escolha() }));
    await exibirComoFoi(7);
    await exibirComoFoi("7");
    expect(banco.escritas()).toEqual([]);
  });
});

describe("responderComoFoi", () => {
  it("Amei grava a reação, 'Já assisti', a resposta e o evento", async () => {
    const banco = logado({ id: "u-1" }, bancoFalso({ linha: escolha() }));

    expect(await responderComoFoi({}, formulario({ id: "7", resposta: "amei" }))).toEqual({});

    expect(definirReacao).toHaveBeenCalledWith(expect.anything(), "u-1", 550, "amei");
    expect(definirLista).toHaveBeenCalledWith(expect.anything(), "u-1", 550, "assistido");
    const [update, evento] = banco.escritas();
    expect(update).toMatchObject({ tabela: "escolhas_noite", filtros: [["id", 7]] });
    expect(update!.valor).toHaveProperty("respondido_em");
    expect(evento).toMatchObject({ valor: { nome: "como_foi_respondido", dados: { resposta: "amei" } } });
  });

  it("'Não cheguei a ver' só marca como respondida", async () => {
    const banco = logado({ id: "u-1" }, bancoFalso({ linha: escolha() }));

    expect(await responderComoFoi({}, formulario({ id: "7", resposta: "nao-vi" }))).toEqual({});

    expect(definirReacao).not.toHaveBeenCalled();
    expect(definirLista).not.toHaveBeenCalled();
    expect(banco.escritas().map((c) => c.tabela)).toEqual(["escolhas_noite", "eventos"]);
  });

  it("se a reação falha, a pergunta continua pendente", async () => {
    const banco = logado({ id: "u-1" }, bancoFalso({ linha: escolha() }));
    vi.mocked(definirReacao).mockResolvedValue({ ok: false, erro: "banco" });

    const estado = await responderComoFoi({}, formulario({ id: "7", resposta: "gostei" }));

    expect(estado.mensagem).toMatch(/Não foi possível salvar/);
    expect(definirLista).not.toHaveBeenCalled();
    expect(banco.escritas()).toEqual([]);
  });

  it.each([
    ["escolha inexistente", null, { ok: false, erro: "nao-encontrada" }],
    ["escolha já respondida", escolha({ respondido_em: horasAtras(1) }), { ok: true, tmdbId: 550 }],
  ])("%s não grava nada", async (_caso, linha, esperado) => {
    const banco = bancoFalso({ linha });

    expect(await gravarResposta(banco.cliente, "u-1", 7, "amei")).toEqual(esperado);
    expect(definirReacao).not.toHaveBeenCalled();
    expect(banco.escritas()).toEqual([]);
  });

  it("recusa resposta fora da lista e pede login sem sessão", async () => {
    logado({ id: "u-1" }, bancoFalso({ linha: escolha() }));
    expect((await responderComoFoi({}, formulario({ id: "7", resposta: "odiei" }))).mensagem).toMatch(
      /Não foi possível/,
    );
    logado(null);
    expect(await responderComoFoi({}, formulario({ id: "7", resposta: "amei" }))).toEqual({
      mensagem: "Sua sessão expirou. Entre de novo.",
    });
  });
});

