    const banco = logado({ id: "u-1" }, bancoFalso({ linha: escolha({ vezes_perguntado: 1, perguntado_em: horasAtras(20) }) }));

    await exibirComoFoi(7);

    const [update, evento] = banco.escritas();
    expect(update).toMatchObject({
      tabela: "escolhas_noite",
      valor: { vezes_perguntado: 2 },
      filtros: [["id", 7], ["vezes_perguntado", 1]],
    });
    expect(evento).toMatchObject({ tabela: "eventos", valor: { nome: "como_foi_exibido", dados: {} } });
  });

  it("na mesma visita, não grava nada", async () => {
    const banco = bancoFalso({ linha: escolha({ vezes_perguntado: 1, perguntado_em: horasAtras(0.2) }) });

    expect(await contarExibicao(banco.cliente, 7)).toBe(false);
    expect(banco.escritas()).toEqual([]);
  });

  it("não grava nada sem sessão ou com ID inválido", async () => {
    const banco = logado(null, bancoFalso({ linha: escolha() }));
    await exibirComoFoi(7);
    await exibirComoFoi("7");
    expect(banco.escritas()).toEqual([]);
  });
});

