    expect(definirLista).not.toHaveBeenCalled();
    expect(banco.escritas().map((c) => c.tabela)).toEqual(["escolhas_noite", "eventos"]);
  });

  it("se a reação falha, a pergunta continua pendente", async () => {
    const banco = logado({ id: "u-1" }, bancoFalso({ linha: escolha() }));
    vi.mocked(definirReacao).mockResolvedValue({ ok: false, erro: "banco" });

